(assert (= "1.12.6" (clojure-version)))
(defn case-escape-control [^long n] (let [n (long n)] (loop [i 0 acc 0.0] (if (< i n) (let [x (+ 3000000000 i) y (double i)] (recur (inc i) (unchecked-add acc (double (+ x y))))) acc))))
(let [actual (case-escape-control 10)] (prn "escape-control" 10 actual) (assert (== 30000000090.0 actual)))
(let [actual (case-escape-control 1000000)] (prn "escape-control" 1000000 actual) (assert (== 3000999999000000.0 actual)))
(let [actual (case-escape-control 2000000)] (prn "escape-control" 2000000 actual) (assert (== 6003999998000000.0 actual)))
(defn case-escape-vector [^long n] (let [n (long n)] (loop [i 0 acc 0.0] (if (< i n) (let [x (+ 3000000000 i) y (double i)] (recur (inc i) (unchecked-add acc (double (let [[a b] [x y]] (+ a b)))))) acc))))
(let [actual (case-escape-vector 10)] (prn "escape-vector" 10 actual) (assert (== 30000000090.0 actual)))
(let [actual (case-escape-vector 1000000)] (prn "escape-vector" 1000000 actual) (assert (== 3000999999000000.0 actual)))
(let [actual (case-escape-vector 2000000)] (prn "escape-vector" 2000000 actual) (assert (== 6003999998000000.0 actual)))
(defn case-escape-entry [^long n] (let [n (long n)] (loop [i 0 acc 0.0] (if (< i n) (let [x (+ 3000000000 i) y (double i)] (recur (inc i) (unchecked-add acc (double (let [[a b] (clojure.lang.MapEntry/create x y)] (+ a b)))))) acc))))
(let [actual (case-escape-entry 10)] (prn "escape-entry" 10 actual) (assert (== 30000000090.0 actual)))
(let [actual (case-escape-entry 1000000)] (prn "escape-entry" 1000000 actual) (assert (== 3000999999000000.0 actual)))
(let [actual (case-escape-entry 2000000)] (prn "escape-entry" 2000000 actual) (assert (== 6003999998000000.0 actual)))
(defn case-escape-closure [^long n] (let [n (long n)] (loop [i 0 acc 0.0] (if (< i n) (let [x (+ 3000000000 i) y (double i)] (recur (inc i) (unchecked-add acc (double (let [f (fn [] (+ x y))] (f)))))) acc))))
(let [actual (case-escape-closure 10)] (prn "escape-closure" 10 actual) (assert (== 30000000090.0 actual)))
(let [actual (case-escape-closure 1000000)] (prn "escape-closure" 1000000 actual) (assert (== 3000999999000000.0 actual)))
(let [actual (case-escape-closure 2000000)] (prn "escape-closure" 2000000 actual) (assert (== 6003999998000000.0 actual)))
